CREATE OR REPLACE VIEW `view_letzte_schicht` AS
with aktuelle_spät as (select case when (select cast(max(`tbl_ueb_fz_buchungen`.`filedate`) as time) from `tbl_ueb_fz_buchungen`) > '14:05:00' then curdate() else (select max(`tbl_datum`.`datum`) from `tbl_datum` where `tbl_datum`.`datum` < curdate() and `tbl_datum`.`arbeitstag` = 1) end AS `datum`), aktuelle_schicht as (select `aktuelle_spät`.`datum` AS `datum`,if(week(`aktuelle_spät`.`datum`) = week(curdate()),'Spät','Nacht') AS `Schicht` from `aktuelle_spät` union all values (curdate(),'Nacht'),(curdate(),'Früh')), buchungen as (select `b`.`PersNr` AS `persnr`,`b`.`Datum` AS `Datum`,`b`.`Status` AS `status`,`b`.`Schicht` AS `schicht`,if(`p`.`eg` = 'ZAK',1,0) AS `zak` from ((`aktuelle_schicht` `ls` left join `tbl_ueb_fz_buchungen` `b` on(`ls`.`datum` = `b`.`Datum` and `ls`.`Schicht` = `b`.`Schicht`)) left join `tbl_ueb_personalakte_scd` `p` on(`b`.`PersNr` = `p`.`persnr` and `b`.`Datum` between `p`.`gueltig_von` and `p`.`gueltig_bis`)) where `p`.`taetigkeit` = 'Lagerhelfer'), kq_ist as (select if(`b`.`Datum` <> curdate(),'Spät',`b`.`schicht`) AS `schicht`,`b`.`zak` AS `zak`,sum(`ag`.`krank` = 1) AS `krank`,sum(`ag`.`anwesenheit` <> 'Frei') AS `alle`,sum(`ag`.`krank` = 1) / sum(`ag`.`anwesenheit` <> 'Frei') AS `kq` from (`buchungen` `b` left join `tbl_abwesenheitsgrund` `ag` on(`b`.`status` = `ag`.`kuerzel`)) group by `b`.`Datum`,`b`.`schicht`,`b`.`zak`)select `kq_ist`.`schicht` AS `schicht`,`kq_ist`.`zak` AS `zak`,`kq_ist`.`krank` AS `krank`,`kq_ist`.`alle` AS `alle`,`kq_ist`.`kq` AS `kq` from `kq_ist`;
